/* ---------- chest generators ("lockpicking"): randomized applied questions ---------- */
const IHRM_GENS = [];
const IG = (c, make) => IHRM_GENS.push({ c, d: 3, make });
const iRp = (r, a) => a[Math.floor(r() * a.length)];
const iOpts = (ans, list) => [ans, ...list.filter(x => x !== ans).slice(0, 3)];
IG(9, r => {
  const s = iRp(r, [["A high-potential executive joins an elite cadre with a long-term international track", "Full International"], ["A technical expert transfers skills to a client team for 18 months, then returns", "Expat Lite"], ["A middle manager volunteers to relocate, and the firm wants lower cost", "Local Plus"], ["A manager wants to stay in the host country after a five-year contract ends", "Localization"]]);
  return { q: `${s[0]}. Which Table 9.7 policy fits?`, a: iOpts(s[1], ["Full International", "Expat Lite", "Local Plus", "Localization"]), e: "Table 9.7: Full International = development. Expat Lite = skills/secondment. Local Plus = cost savings. Localization = cost savings, turnover, and retention." };
});
IG(8, r => {
  const g = iRp(r, [["Talent planning", "Core function"], ["Talent acquisition", "Core function"], ["Knowledge spillovers", "MTM process"], ["Institutional support", "MTM process"], ["Educational leadership", "MTM process"], ["National culture", "Macro environmental factor"], ["Demographics", "Macro environmental factor"], ["Global labor markets", "Macro environmental factor"], ["Educational attainment", "First-level outcome"], ["Diaspora utilization", "First-level outcome"], ["Innovation", "Second-level outcome"], ["Economic development", "Second-level outcome"]]);
  return { q: `Where does "${g[0]}" sit in the MTM framework (Figure 8.3)?`, a: iOpts(g[1], ["Core function", "MTM process", "Macro environmental factor", "First-level outcome", "Second-level outcome"]), e: "Figure 8.3 blocks: macro environmental factors → core functions and MTM processes → first- and second-level outcomes." };
});
IG(9, r => {
  const base = iRp(r, [120000, 150000, 180000, 200000, 240000]), pct = iRp(r, [10, 15, 20, 25]), kind = iRp(r, ["overseas service premium", "hardship allowance"]), ans = base * pct / 100;
  const f = n => "$" + n.toLocaleString("en-US");
  return { q: `An expatriate has a base salary of ${f(base)}. The ${kind} is ${pct}% of base. How much is the ${kind} per year?`, a: [f(ans), f(ans * 2), f(Math.round(ans / 2)), f(base - ans)], e: `${pct}% × ${f(base)} = ${f(ans)}. This follows the Table 9.5 worksheet, where a 20% premium on a 200,000 base is 40,000.`, calc: true };
});
IG(9, r => {
  const amt = iRp(r, [20000, 30000, 40000, 50000]), [yr, p] = iRp(r, [["one", 100], ["two", 50], ["three", 20]]), f = n => "$" + n.toLocaleString("en-US"), ans = amt * p / 100;
  return { q: `A Local Plus assignee starts with a ${f(amt)} housing allowance. Using the Table 9.7 phase-out, how much is paid in year ${yr}?`, a: [...new Set([f(ans), f(amt), f(amt / 2), f(amt / 5), f(amt * 0.75)])].slice(0, 4), e: `Phase-out: 100% in year one, 50% in year two, 20% in year three. ${p}% × ${f(amt)} = ${f(ans)}.`, calc: true };
});
IG(8, r => {
  const n = iRp(r, [200, 500, 1000, 2500]), [band, p, treat] = iRp(r, [["top", 20, "reward and promote"], ["middle", 70, "develop and manage"], ["bottom", 10, "fire"]]);
  return { q: `A firm with ${n} employees applies Jack Welch's rule. How many employees fall in the ${band} band, and what happens to them?`, a: [`${n * p / 100}: ${treat}`, `${n * (p === 70 ? 20 : 70) / 100}: ${treat}`, `${n * p / 100}: ${band === "bottom" ? "develop and manage" : "fire"}`, `${n * (p === 10 ? 20 : 10) / 100}: ${band === "top" ? "develop and manage" : "reward and promote"}`], e: "Top 20% reward and promote. Middle 70% develop and manage. Bottom 10% fire. The slide shows this as a caution." };
});
IG(10, r => {
  const g = iRp(r, [["PESTLE", "External factors"], ["Asymmetric events", "External factors"], ["Environmental dynamics", "External factors"], ["MNE structure", "Organizational factors"], ["Corporate governance", "Organizational factors"], ["MNE culture", "Organizational factors"], ["HR practices", "HR function"], ["Crisis management and co-ordination", "HR function"], ["Financial performance", "MNE performance"], ["Enterprise resilience", "MNE performance"]]);
  return { q: `Where does "${g[0]}" sit in the strategic HRM model (Figure 10.1)?`, a: iOpts(g[1], ["External factors", "Organizational factors", "HR function", "MNE performance"]), e: "Figure 10.1: external and organizational factors work with the HR function, which leads to MNE performance." };
});
IG(10, r => {
  const g = iRp(r, [["paying a clerk a small fee to speed a routine visa stamp", "Facilitating (grease) payment"], ["paying a small fee to get a phone line installed sooner", "Facilitating (grease) payment"], ["paying a minister to award a public contract", "Bribe under the FCPA"], ["promising an official's child a job to win a license", "Bribe under the FCPA"], ["paying for an SOE buyer's resort trip before a contract award", "Bribe under the FCPA"], ["having a local agent pass cash to an official for a tender", "Bribe under the FCPA"]]);
  return { q: `Under the Chapter 10 slides, how would you label ${g[0]}?`, a: iOpts(g[1], ["Facilitating (grease) payment", "Bribe under the FCPA", "Ordinary legal expense", "Tax protection payment"]), e: "A grease payment expedites or secures a routine government action. A bribe influences an official to get or keep business or an improper advantage." };
});
IG(10, r => {
  const g = iRp(r, [["'Local custom decides; there is no universal right or wrong.'", "Ethical relativism"], ["'Do what you would do at home.'", "Ethical absolutism"], ["'Some principles of right and wrong transcend culture.'", "Ethical universalism"]]);
  return { q: `A manager says: ${g[0]} Which position is this?`, a: iOpts(g[1], ["Ethical relativism", "Ethical absolutism", "Ethical universalism", "Ethical polycentrism"]), e: "Relativism: no universal rights or wrongs. Absolutism: do what you would do at home. Universalism: principles transcend culture." };
});

